# Simulating CP vs AP trade-offs in a two-node key-value store
class Node:
    def __init__(self, name):
        self.name = name
        self._data = {}
        self.partitioned = False

    def write(self, key, value):
        self._data[key] = value

    def read(self, key):
        return self._data.get(key)

def ap_read(primary, replica, key):
    """AP: always respond, even if replica is stale."""
    return replica.read(key)  # may be stale but never errors

def cp_read(primary, replica, key):
    """CP: refuse if we cannot confirm consistency with primary."""
    if replica.partitioned:
        return 'ERROR: cannot confirm consistency (partition detected)'
    return replica.read(key)

primary = Node('primary')
replica = Node('replica')

primary.write('balance', 1000)
replica.write('balance', 1000)
primary.write('balance', 750)   # replica missed this update
replica.partitioned = True

print(f'AP read (stale ok):  balance = {ap_read(primary, replica, "balance")}')
print(f'CP read (safe only): balance = {cp_read(primary, replica, "balance")}')
